changeSet.sql:
ALTER TABLE users
    ADD COLUMN first_name VARCHAR(255) NULL AFTER name,
    ADD COLUMN last_name VARCHAR(255) NULL AFTER first_name;
UPDATE users SET
    first_name = TRIM(SUBSTRING_INDEX(name, ' ', 1)),
    last_name = TRIM(CASE
        WHEN LOCATE(' ', name) = 0 THEN ''
        ELSE SUBSTRING(name, LOCATE(' ', name) + 1)
    END)
WHERE first_name IS NULL;
UPDATE users SET first_name = '' WHERE first_name IS NULL;
UPDATE users SET last_name = '' WHERE last_name IS NULL;
ALTER TABLE users
    MODIFY first_name VARCHAR(255) NOT NULL,
    MODIFY last_name VARCHAR(255) NOT NULL;
